            SPFRecordTerm([string]$term) {
                $this.term = $term
                $match = [regex]::Match($term, $this.matchTerms, $this.option)
                $this.directive = ($match.Groups | Where-Object { $_.Name -eq "directive" }).Value
                $qVal = ($match.Groups | Where-Object { $_.Name -eq "qual" }).Value
