            }
            $spfRecord = [pscustomobject]@{ record = $Record; terms = @($terms) }
            $spfLookups = @($terms | Where-Object { $_.mechanism -eq 'include' } | ForEach-Object {
                    [pscustomobject]@{ SPFSourceDomain = $_.mechanismTarget; Include = $true }
                })
        }

